local _, WFJ = ...
WFJ.Data.add("book", {
  ["d436c11174d4c9cb"] = { "Le forze rimaste dell'⟦Alliance=Alleanza⟧ al comando di Jaina Proudmoore si stabilirono nel sud di Kalimdor. Al largo della costa orientale di ⟦Dustwallow Marsh=Acquemorte⟧ costruirono l'aspra città portuale di Theramore. Lì gli umani e i loro alleati nani lottarono per sopravvivere in una terra che sarebbe sempre stata loro ostile. Benché i difensori di Durotar e di Theramore rispettassero la precaria tregua reciproca, la fragile serenità coloniale non era destinata a durare.", "." },
  ["d4792a104ca2ff17"] = { "LEGGENDE DEI TROLL, VOLUME III\n\rLa ⟦Stone of the Tides=Pietra delle Maree⟧\n\nPer mano\n\rdell'arcimago Ansirem Runeweaver\n\rDalaran\n\nINTRODUZIONE\n\nL'antico Impero Gurubashi fu la fonte di molte leggende affascinanti e intriganti, senza dubbio riconducibili al suo ambiente, poiché lo studio delle sue credenze e delle sue pratiche sociali ha rivelato una grande venerazione per la natura circostante.\n\nPur avendo approfondito molti", "." },
  ["d479cd59405f8a76"] = { "Gli alti elfi, guidati da Dath'Remar, si lasciarono alle spalle Kalimdor e sfidarono le tempeste del Maelstrom. Le loro flotte vagarono per molti lunghi anni tra i relitti del mondo e, durante il loro viaggio, scoprirono misteri e regni perduti. Dath'Remar, che aveva assunto il nome di Sunstrider (ovvero «colui che cammina nel giorno»), cercava luoghi dove le linee di potere fossero particolarmente forti, su cui fondare una nuova patria per il suo popolo.", "." },
  ["d4968560eafb45ab"] = { "Nella loro furia, i draghi di Alexstrasza fecero a pezzi Grim Batol e incenerirono gran parte del clan delle Fauci di Drago. I grandiosi progetti di riunificazione di Nekros crollarono, mentre le truppe dell'⟦Alliance=Alleanza⟧ radunavano gli orchi sopravvissuti e li gettavano nei campi di internamento che li attendevano. La sconfitta delle Fauci di Drago segnò la fine dell'⟦Horde=Orda⟧, e la fine della furiosa sete di sangue degli orchi.", "." },
})
